'use client';

import { WordRoll } from '@/components/core/word-roll';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { GitBranchIcon, GitMergeIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ChecksBox } from './checks';
import { CODER, ISSUE } from './data';
import {
  allChecksPassed,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type IssueStatus,
  type MergeStatus,
  type PlanStatus,
} from './session';
import { CoderTile, Timeline } from './timeline';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const STATUS_WORD: Record<IssueStatus, string> = {
  planned: 'Planned',
  progress: 'In progress',
  review: 'In review',
  merged: 'Merged',
};

const STATUS_LABELS = Object.values(STATUS_WORD);

const STATUS_COLOR: Record<IssueStatus, string> = {
  planned: 'var(--muted-foreground)',
  progress: 'var(--info)',
  review: 'var(--warning)',
  merged: 'var(--success)',
};

const MERGE_LABELS: Record<MorphState, string> = {
  idle: 'Merge pull request',
  busy: 'Merging',
  done: 'Merged',
};

function mergeHintOf(plan: PlanStatus, canMerge: boolean, merge: MergeStatus) {
  if (merge === 'done') {
    return 'Merged into main';
  }
  if (plan === 'pending') {
    return 'Starts with your approval of the plan';
  }
  if (plan === 'changes') {
    return 'Stopped: the plan needs a new brief';
  }
  if (canMerge) {
    return 'Every check passed';
  }
  return 'Available once every check passes';
}

function branchWordOf(isDeleted: boolean) {
  if (isDeleted) {
    return 'Deleted';
  }
  return 'Open';
}

function StatusChip({ status }: { status: IssueStatus }) {
  return (
    <Chip
      color={STATUS_COLOR[status]}
      className='transition-colors duration-300'
    >
      <WordRoll text={STATUS_WORD[status]} labels={STATUS_LABELS} />
    </Chip>
  );
}

function PropertyRow({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className='flex min-h-8 items-center gap-3 text-[13px]'>
      <dt className='text-muted-foreground w-20 shrink-0'>{label}</dt>
      <dd className='flex min-w-0 flex-1 items-center gap-2'>{children}</dd>
    </div>
  );
}

export default function AgentReview01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const canMerge = allChecksPassed(state.checks);
  const mergeHint = mergeHintOf(state.plan, canMerge, state.merge);
  const hasStopped = state.plan === 'changes';
  const isOver = isFinished || hasStopped;
  const canReplay = isOver && !isAutoplaying;
  const hasActivity = state.events.length > 0;
  const branchWord = branchWordOf(state.isBranchDeleted);
  const announcement = `${ISSUE.id} is ${STATUS_WORD[state.status]}. ${mergeHint}`;
  const message = spokenUnless(isAutoplaying, announcement);

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-4 @3xl:p-8'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-6'>
          <header className='flex flex-col gap-2'>
            <div className='flex flex-wrap items-center gap-2'>
              <span className='text-muted-foreground font-mono text-xs'>
                {ISSUE.id}
              </span>
              <StatusChip status={state.status} />
              <span className='ms-auto'>
                <ReplayButton
                  isShown={canReplay}
                  onReplay={restart}
                  label='Replay the task'
                />
              </span>
            </div>
            <h1 className='text-2xl font-semibold text-balance'>
              {ISSUE.title}
            </h1>
          </header>

          <div className='flex flex-col gap-6 @3xl:flex-row @3xl:items-start'>
            <main className='flex min-w-0 flex-1 flex-col gap-6'>
              <section aria-label='Request' className='flex flex-col gap-1.5'>
                <h2 className='text-muted-foreground text-xs'>Request</h2>
                <p className='text-sm leading-relaxed'>{ISSUE.request}</p>
              </section>
              <section className='flex flex-col gap-3'>
                <h2 className='text-muted-foreground text-xs'>Activity</h2>
                {!hasActivity && (
                  <p className='text-muted-foreground text-[13px]'>
                    Nothing yet. Coder starts with a plan for you to approve.
                  </p>
                )}
                <Timeline
                  events={state.events}
                  plan={state.plan}
                  pressed={pressed}
                  onDecide={(decision) =>
                    act({ type: 'planDecided', decision })
                  }
                />
              </section>
            </main>

            <aside className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col gap-5 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:w-80 @3xl:shrink-0'>
              <dl className='flex flex-col'>
                <PropertyRow label='Assignee'>
                  <CoderTile />
                  {CODER.name}
                </PropertyRow>
                <PropertyRow label='Branch'>
                  <GitBranchIcon className='text-muted-foreground size-3.5 shrink-0' />
                  <code className='min-w-0 truncate font-mono text-xs'>
                    {ISSUE.branch}
                  </code>
                </PropertyRow>
                <PropertyRow label='State'>
                  <Swap swapKey={branchWord}>{branchWord}</Swap>
                  {state.isBranchDeleted && (
                    <Button
                      type='button'
                      variant='ghost'
                      size='sm'
                      onClick={() => act({ type: 'branch', isDeleted: false })}
                      className='text-primary-ink -my-1 transition-opacity duration-300 starting:opacity-0'
                    >
                      Restore
                    </Button>
                  )}
                </PropertyRow>
              </dl>

              <ChecksBox checks={state.checks} />

              <div className='flex flex-col gap-2'>
                <MorphButton
                  type='button'
                  size='lg'
                  state={state.merge}
                  labels={MERGE_LABELS}
                  idleIcon={<GitMergeIcon />}
                  disabled={!canMerge}
                  onClick={() => act({ type: 'merge' })}
                  className={pressedSolidOf(pressed === 'merge')}
                />
                <p className='text-muted-foreground text-center text-xs'>
                  <Swap swapKey={mergeHint}>{mergeHint}</Swap>
                </p>
              </div>
            </aside>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';

import {
  ACTIVITY,
  CODER,
  DIFF_STATS,
  ISSUE,
  PLAN_STEPS,
  REVIEWER,
  type Activity,
} from './data';
import type { PlanDecision, PlanStatus } from './session';

export function CoderTile() {
  const gemStyle = {
    '--gem': seriesColorOf(CODER.series),
  } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={gemStyle}
      className='gem-plate inline-flex size-6 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold select-none'
    >
      {CODER.initial}
    </span>
  );
}

function ActorMark({ actor }: { actor: Activity['actor'] }) {
  if (actor === 'coder') {
    return <CoderTile />;
  }
  return (
    <Avatar className='size-6'>
      <AvatarImage src={REVIEWER.avatar} alt='' />
      <AvatarFallback className='text-[9px]'>
        {REVIEWER.initials}
      </AvatarFallback>
    </Avatar>
  );
}

function actorNameOf(actor: Activity['actor']) {
  if (actor === 'coder') {
    return CODER.name;
  }
  return REVIEWER.name;
}

type PlanBodyProps = {
  plan: PlanStatus;
  pressed: string | null;
  onDecide: (decision: PlanDecision) => void;
};

function PlanBody({ plan, pressed, onDecide }: PlanBodyProps) {
  const isPending = plan === 'pending';

  return (
    <div className='bg-foreground/[0.04] mt-2 flex flex-col gap-1 rounded-lg p-3'>
      <ol className='flex flex-col gap-1.5 text-[13px]'>
        {PLAN_STEPS.map((step, index) => (
          <li key={step} className='flex gap-2.5'>
            <span className='text-muted-foreground w-3 shrink-0 tabular-nums'>
              {index + 1}
            </span>
            {step}
          </li>
        ))}
      </ol>
      <Fold open={isPending}>
        <div className='flex flex-wrap items-center gap-2 pt-2'>
          <Button
            type='button'
            size='sm'
            onClick={() => onDecide('approved')}
            className={pressedSolidOf(pressed === 'approve')}
          >
            Approve the plan
          </Button>
          <Button
            type='button'
            size='sm'
            variant='outline'
            onClick={() => onDecide('changes')}
          >
            Ask for changes
          </Button>
          <span className='text-muted-foreground text-xs'>
            Nothing is written before you approve
          </span>
        </div>
      </Fold>
    </div>
  );
}

function DiffBar() {
  const total = DIFF_STATS.additions + DIFF_STATS.deletions;
  const addedShare = DIFF_STATS.additions / total;
  const addedStyle = { transform: `scaleX(${addedShare})` };

  return (
    <span
      aria-hidden='true'
      className='bg-destructive/50 relative h-1.5 w-16 overflow-hidden rounded-full'
    >
      <span
        style={addedStyle}
        className='bg-success absolute inset-0 origin-left'
      />
    </span>
  );
}

function PullRequestBody() {
  return (
    <div className='bg-foreground/[0.04] mt-2 flex flex-wrap items-center gap-x-3 gap-y-2 rounded-lg p-3'>
      <BrandTile brand='github' size='lg' title='GitHub' />
      <span className='min-w-40 flex-1 text-[13px] font-medium'>
        {ISSUE.pullRequest}
      </span>
      <span className='flex items-center gap-2 text-xs tabular-nums'>
        <span className='text-success-foreground'>+{DIFF_STATS.additions}</span>
        <span className='text-destructive-ink'>-{DIFF_STATS.deletions}</span>
        <DiffBar />
        <span className='text-muted-foreground'>{DIFF_STATS.files} files</span>
      </span>
    </div>
  );
}

function EntryText({ entry }: { entry: Activity }) {
  const name = actorNameOf(entry.actor);

  if (entry.kind === 'commit') {
    return (
      <p className='text-[13px] leading-6'>
        <span className='font-medium'>{name}</span>{' '}
        <span className='text-muted-foreground'>pushed</span>{' '}
        <code className='bg-foreground/[0.05] rounded-sm px-1 py-0.5 font-mono text-xs'>
          {entry.hash}
        </code>{' '}
        {entry.text}
      </p>
    );
  }
  return (
    <p className='text-[13px] leading-6'>
      <span className='font-medium'>{name}</span>{' '}
      <span className='text-muted-foreground'>{entry.text}</span>
    </p>
  );
}

type TimelineProps = PlanBodyProps & {
  events: string[];
};

export function Timeline({ events, plan, pressed, onDecide }: TimelineProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const lastId = events.at(-1);

  return (
    <ol aria-label='Activity' className='flex flex-col'>
      <AnimatePresence initial={false}>
        {events.map((id) => {
          const entry = ACTIVITY[id];
          const isLast = id === lastId;
          return (
            <motion.li key={id} className='overflow-hidden' {...rowPresence}>
              <div className='relative flex gap-3 pb-4'>
                {!isLast && (
                  <span
                    aria-hidden='true'
                    className='bg-border absolute top-7 bottom-1 left-3 w-px'
                  />
                )}
                <ActorMark actor={entry.actor} />
                <div className='min-w-0 flex-1'>
                  <EntryText entry={entry} />
                  {entry.kind === 'plan' && (
                    <PlanBody
                      plan={plan}
                      pressed={pressed}
                      onDecide={onDecide}
                    />
                  )}
                  {entry.kind === 'pull-request' && <PullRequestBody />}
                </div>
              </div>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ol>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { Badge } from '@/registry/ndeko/ui/badge';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { CHECKS, type CheckId } from './data';
import { passedCountOf, type Check } from './session';

function fillOf(passed: number) {
  const share = passed / CHECKS.length;
  return { transform: `scaleX(${share})` };
}

function CheckRow({ name, check }: { name: string; check: Check }) {
  const isRunning = check.status === 'running';
  const isRerun = check.attempt > 1;

  return (
    <li className='flex h-9 items-center gap-2.5 text-[13px]'>
      <CallStatusMark status={check.status} />
      <span className='min-w-0 flex-1 truncate'>{name}</span>
      {isRerun && (
        <Badge
          variant='secondary'
          className='transition-opacity duration-300 starting:opacity-0'
        >
          Run {check.attempt}
        </Badge>
      )}
      <LiveDuration
        item={check}
        isRunning={isRunning}
        className='text-muted-foreground w-10 shrink-0 text-end text-xs'
      />
    </li>
  );
}

type ChecksBoxProps = {
  checks: Record<CheckId, Check> | null;
};

export function ChecksBox({ checks }: ChecksBoxProps) {
  const passed = passedCountOf(checks);

  return (
    <section aria-label='Checks' className='flex flex-col gap-3'>
      <div className='flex items-end justify-between gap-3'>
        <h3 className='text-sm font-medium'>Checks</h3>
        <p className='text-muted-foreground text-xs'>
          <MotionNumber
            value={passed}
            className='text-foreground text-xl leading-none font-semibold'
          />{' '}
          of {CHECKS.length} passed
        </p>
      </div>
      <div
        role='progressbar'
        aria-label='Checks passed'
        aria-valuemin={0}
        aria-valuemax={CHECKS.length}
        aria-valuenow={passed}
        className='bg-foreground/[0.06] h-1.5 overflow-hidden rounded-full'
      >
        <div
          style={fillOf(passed)}
          className='bg-success h-full origin-left rounded-full transition-transform duration-500 ease-(--ease-out-strong)'
        />
      </div>
      {!checks && (
        <p className='text-muted-foreground text-[13px]'>
          Checks start when the pull request opens
        </p>
      )}
      {checks && (
        <ul className='flex flex-col'>
          {CHECKS.map((check) => (
            <CheckRow
              key={check.id}
              name={check.name}
              check={checks[check.id]}
            />
          ))}
        </ul>
      )}
    </section>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import type { CallStatus } from '@/registry/ndeko/lib/agent-run';

import type { CheckId } from './data';

export type IssueStatus = 'planned' | 'progress' | 'review' | 'merged';

export type PlanStatus = 'pending' | 'approved' | 'changes';

export type MergeStatus = 'idle' | 'busy' | 'done';

export type Check = {
  status: CallStatus;
  attempt: number;
  startedAt?: number;
  endedAt?: number;
};

export type TaskState = {
  status: IssueStatus;
  events: string[];
  plan: PlanStatus;
  checks: Record<CheckId, Check> | null;
  merge: MergeStatus;
  isBranchDeleted: boolean;
};

export type PlanDecision = 'approved' | 'changes';

export type TaskAction =
  | { type: 'event'; id: string }
  | { type: 'status'; status: IssueStatus }
  | { type: 'planDecided'; decision: PlanDecision }
  | { type: 'checksStarted' }
  | { type: 'check'; id: CheckId; status: CallStatus }
  | { type: 'rerun'; id: CheckId }
  | { type: 'merge' }
  | { type: 'merged' }
  | { type: 'branch'; isDeleted: boolean }
  | { type: 'work'; actions: TaskAction[] };

type Step = SessionStep<TaskState, TaskAction>;

export const INITIAL: TaskState = {
  status: 'planned',
  events: [],
  plan: 'pending',
  checks: null,
  merge: 'idle',
  isBranchDeleted: false,
};

export function allChecksPassed(checks: Record<CheckId, Check> | null) {
  if (!checks) {
    return false;
  }
  const all = Object.values(checks);
  return all.every((check) => check.status === 'done');
}

export function passedCountOf(checks: Record<CheckId, Check> | null) {
  if (!checks) {
    return 0;
  }
  const all = Object.values(checks);
  const passed = all.filter((check) => check.status === 'done');
  return passed.length;
}

function planDecided(state: TaskState, decision: PlanDecision): TaskState {
  if (state.plan !== 'pending') {
    return state;
  }
  if (decision === 'changes') {
    return { ...state, plan: 'changes', events: [...state.events, 'changes'] };
  }
  return {
    ...state,
    plan: 'approved',
    status: 'progress',
    events: [...state.events, 'approved'],
  };
}

function runningCheck(now: number, attempt: number): Check {
  return { status: 'running', attempt, startedAt: now };
}

function checkUpdated(
  state: TaskState,
  id: CheckId,
  status: CallStatus,
  now: number
): TaskState {
  if (!state.checks) {
    return state;
  }
  const check: Check = { ...state.checks[id], status, endedAt: now };
  return { ...state, checks: { ...state.checks, [id]: check } };
}

function rerun(state: TaskState, id: CheckId, now: number): TaskState {
  if (!state.checks) {
    return state;
  }
  const attempt = state.checks[id].attempt + 1;
  const check = runningCheck(now, attempt);
  return { ...state, checks: { ...state.checks, [id]: check } };
}

function merge(state: TaskState): TaskState {
  const canMerge = allChecksPassed(state.checks) && state.merge === 'idle';
  if (!canMerge) {
    return state;
  }
  return { ...state, merge: 'busy' };
}

function merged(state: TaskState): TaskState {
  if (state.merge !== 'busy') {
    return state;
  }
  return {
    ...state,
    merge: 'done',
    status: 'merged',
    events: [...state.events, 'merged'],
  };
}

function branchChanged(state: TaskState, isDeleted: boolean): TaskState {
  if (isDeleted) {
    return { ...state, isBranchDeleted: true };
  }
  const events = [...state.events, 'restored'];
  return { ...state, isBranchDeleted: false, events };
}

/** The agent only works once a person has approved its plan. */
function work(state: TaskState, actions: TaskAction[], now: number) {
  if (state.plan !== 'approved') {
    return state;
  }
  let next = state;
  for (const inner of actions) {
    next = applyAt(next, inner, now);
  }
  return next;
}

export function applyAt(
  state: TaskState,
  action: TaskAction,
  now: number
): TaskState {
  switch (action.type) {
    case 'event':
      return { ...state, events: [...state.events, action.id] };
    case 'status':
      return { ...state, status: action.status };
    case 'planDecided':
      return planDecided(state, action.decision);
    case 'checksStarted':
      return {
        ...state,
        checks: {
          lint: runningCheck(now, 1),
          build: runningCheck(now, 1),
          tests: runningCheck(now, 1),
        },
      };
    case 'check':
      return checkUpdated(state, action.id, action.status, now);
    case 'rerun':
      return rerun(state, action.id, now);
    case 'merge':
      return merge(state);
    case 'merged':
      return merged(state);
    case 'branch':
      return branchChanged(state, action.isDeleted);
    case 'work':
      return work(state, action.actions, now);
  }
}

export function reducer(state: TaskState, action: TaskAction) {
  return applyAt(state, action, Date.now());
}

function workStep(after: number, actions: TaskAction[]): Step {
  return { after, action: { type: 'work', actions } };
}

function hasDecidedPlan(state: TaskState) {
  return state.plan !== 'pending';
}

function hasPressedMerge(state: TaskState) {
  return state.merge !== 'idle';
}

/** A request that waits on a person is answered by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

export const SCRIPT: Step[] = [
  { after: 1100, action: { type: 'event', id: 'plan' } },
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'approve',
    action: { type: 'planDecided', decision: 'approved' },
    isAnswered: hasDecidedPlan,
  },
  workStep(1500, [{ type: 'event', id: 'commit1' }]),
  workStep(1300, [{ type: 'event', id: 'commit2' }]),
  workStep(1200, [
    { type: 'event', id: 'pr' },
    { type: 'status', status: 'review' },
    { type: 'checksStarted' },
  ]),
  workStep(1200, [{ type: 'check', id: 'lint', status: 'done' }]),
  workStep(700, [{ type: 'check', id: 'build', status: 'done' }]),
  workStep(700, [
    { type: 'check', id: 'tests', status: 'failed' },
    { type: 'event', id: 'failed' },
  ]),
  workStep(1700, [
    { type: 'event', id: 'commit3' },
    { type: 'rerun', id: 'tests' },
  ]),
  workStep(1900, [{ type: 'check', id: 'tests', status: 'done' }]),
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'merge',
    action: { type: 'merge' },
    isAnswered: hasPressedMerge,
  },
  { after: 1100, action: { type: 'merged' } },
  workStep(800, [
    { type: 'event', id: 'branch' },
    { type: 'branch', isDeleted: true },
  ]),
];

function restingOf() {
  let state = INITIAL;
  let now = 1000;
  for (const step of SCRIPT) {
    now += step.after;
    state = applyAt(state, step.action, now);
  }
  return state;
}

export const RESTING = restingOf();

export const LOOP_AFTER_MS = 3800;

import type { SeriesSlot } from '@/registry/ndeko/lib/agent-run';

export const ISSUE = {
  id: 'TAL-128',
  title: 'Export invoices as CSV',
  request:
    'Finance exports invoices by hand every month. Add an Export button to the invoices table that downloads what the current filters show, with dates in ISO format and amounts in the invoice currency.',
  branch: 'tal-128-csv-export',
  pullRequest: 'Add CSV export to the invoices table',
};

export const CODER = { name: 'Coder', initial: 'C', series: 5 as SeriesSlot };

export const REVIEWER = {
